import{topics,blank,load,status}from'./learning.js?v=7';
export const sectors=[{name:'青蓝恒星系',code:'CYAN · 01',subtitle:'数与代数',color:'#75d9eb',ids:['count','fraction','signed','power','expr','factor']},{name:'紫罗兰恒星系',code:'VIOLET · 02',subtitle:'方程与函数',color:'#bca8ff',ids:['equation','system','ineq','quad','linear','inverse','parabola']},{name:'琥珀恒星系',code:'AMBER · 03',subtitle:'图形与几何',color:'#f4bf79',ids:['angle','triangle','pyth','similar','circle']},{name:'翡翠恒星系',code:'JADE · 04',subtitle:'统计与概率',color:'#9de8bd',ids:['stats','prob']}];
export function freshJourney(learning=blank()){return {version:3,learning,current:0,visited:[0],claimed:topics.filter(t=>status(learning,t.id)==='掌握').map(t=>t.id)};}
export function restoreJourney(raw,legacy){try{let v=JSON.parse(raw);if(![2,3].includes(v?.version))return freshJourney(load(legacy));let learning=load(JSON.stringify(v.learning));let visited=[...new Set([0,...(Array.isArray(v.visited)?v.visited:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<4)])];let claimed=[...new Set((Array.isArray(v.claimed)?v.claimed:[]).filter(id=>topics.some(t=>t.id===id)))];if(v.version===2&&claimed.length<visited.length-1)return freshJourney(learning);return {version:3,learning,current:visited.includes(v.current)?v.current:0,visited,claimed};}catch{return freshJourney(load(legacy));}}
export function claim(j,id){if(status(j.learning,id)!=='掌握'||j.claimed.includes(id))return false;j.claimed.push(id);return true;}
export function travel(j,dest){if(!Number.isInteger(dest)||dest<0||dest>=4)return false;if(!j.visited.includes(dest)){j.visited.push(dest);}j.current=dest;return true;}
